
const CFG={scheme:'NFST',ver:2,rules:{cat:'ST',maxIncome:800000,quals:["Master's","MPhil"]},merit:{Academic:40,Proposal:30,Interview:30},docs:['ST Certificate','Income Certificate','Marksheet','Research Admission Letter','Bank Document']};
