const nz=(v,k)=>k=='Income'?String(v).replace(/\D/g,''):String(v).toLowerCase().replace(/[^a-z0-9]/g,'');
const live=c=>`<h3>Live AI document analysis</h3><small>OCR reads the image, then fixed rules compare it with the application. Use sample or dummy documents only.</small><p><input type="file" id="lf" accept="image/*" style="width:auto"> <button class="s" onclick="ai(false)">Analyse image</button> <button class="p" onclick="ai(true)">Try sample certificate</button></p><div id="lr">${c.live?liveRes(c):''}</div>`;
const liveRes=c=>{const L=c.live,a=APPD[c.id]||{};return `<div class="f">Detected: <b>${L.type}</b> <span class="tag ${L.tc<80?'w':'o'}">${L.tc}%</span> ${CFG.docs.includes(L.type)?'':'<span class="tag w">Not a configured document type</span>'}</div><table><tr><th>Field</th><th>Extracted</th><th>Conf.</th><th>Application</th><th>Rule check</th></tr>${L.fields.map(f=>{const av=a[f.k];return `<tr><td>${f.k}</td><td>${f.v}</td><td>${f.c}%</td><td>${av||'-'}</td><td>${av?(nz(av,f.k)==nz(f.v,f.k)?'✓ match':'⚠ mismatch: flag for human review'):'-'}</td></tr>`}).join('')}</table>${L.issues.length?'<div class="f">Quality: '+L.issues.join('; ')+'</div>':''}<small>Engine: ${L.engine||''}. Review signal only; the officer decides.</small>`};
const sampleImg=c=>new Promise(r=>{const v=document.createElement('canvas');v.width=1280;v.height=760;const x=v.getContext('2d');x.scale(2,2);x.fillStyle='#fbfaf3';x.fillRect(0,0,640,380);x.fillStyle='#222';x.font='bold 22px serif';x.fillText(c.id=='C-1042'?'SAMPLE ST CERTIFICATE (dummy)':'SAMPLE INCOME CERTIFICATE (dummy)',40,50);x.font='18px serif';c.x.forEach((q,i)=>x.fillText(q[0]+': '+q[1],40,110+i*40));x.strokeStyle='#999';x.beginPath();x.arc(540,300,40,0,7);x.stroke();v.toBlob(r,'image/png')});

const PROMPT=()=>'You extract fields from an image of an Indian government or academic document for a scholarship verification tool. Reply with only JSON: {"type": one of '+JSON.stringify(CFG.docs.concat('Other'))+',"type_conf":0-100,"fields":[{"k": one of ["Name","DOB","Cert. no.","Income","Issued by","Issue date","Institution","Course","Marks"],"v":"text as printed","c":0-100}],"issues":[short strings for unreadable areas, missing seal or signature, cropped page or expiry]}. Include only fields visible in the image. Do not judge the person or decide eligibility.';
async function prep(f){try{const b=await createImageBitmap(f);const sc=Math.max(1,Math.min(3,1800/b.width));const c=document.createElement('canvas');c.width=Math.round(b.width*sc);c.height=Math.round(b.height*sc);const x=c.getContext('2d');x.fillStyle='#fff';x.fillRect(0,0,c.width,c.height);x.drawImage(b,0,0,c.width,c.height);const im=x.getImageData(0,0,c.width,c.height),p=im.data;let lo=255,hi=0;for(let i=0;i<p.length;i+=4){const g=(p[i]*.3+p[i+1]*.59+p[i+2]*.11)|0;p[i]=p[i+1]=p[i+2]=g;if(g<lo)lo=g;if(g>hi)hi=g}const r=Math.max(1,hi-lo);for(let i=0;i<p.length;i+=4){const g=Math.min(255,Math.max(0,((p[i]-lo)*255/r)|0));p[i]=p[i+1]=p[i+2]=g}x.putImageData(im,0,0);return (await new Promise(q=>c.toBlob(q,'image/png')))||f}catch(e){return f}}
async function ocrLocal(f){const img=await prep(f);const w=await Tesseract.createWorker('eng',1,{workerPath:'lib/worker.min.js',corePath:'lib/core',langPath:'lib/lang',gzip:true,workerBlobURL:false});try{let best=null;for(const m of ['3','6']){await w.setParameters({tessedit_pageseg_mode:m});const {data}=await w.recognize(img);const r=parseOcr(data);if(!best||r.fields.length>best.fields.length)best=r;if(best.fields.length>=3)break}return best}finally{await w.terminate()}}
async function ai(sm){const o=$('lr'),c=cases[sel];try{const loc=typeof Tesseract!='undefined';const S=!loc&&window.claude&&await claude.use('sample');if(!loc&&!S){o.textContent='No OCR engine available in this view.';return}const f=sm?await sampleImg(c):$('lf').files[0];if(!f){o.textContent='Choose an image first.';return}let r;if(loc){o.textContent='Reading with local OCR (first run loads the engine)…';r=await ocrLocal(f)}else{o.textContent='Analysing… (5-60 s, you may be asked to allow this)';const j=await S.json(PROMPT(),{images:f});r={type:j.type||'Other',tc:j.type_conf||0,fields:j.fields||[],issues:j.issues||[]}}r.engine=loc?'Tesseract OCR, runs fully in this browser':'Claude vision';c.live=r;log('AI','Document analysis '+c.id+' ('+r.engine+')','-','Analysed',r.fields.length+' fields, type '+r.type);go()}catch(e){o.textContent={not_granted:'Permission declined, so nothing was sent.',rate_limited:'Too many requests. Wait a moment.',images_unavailable:'Image input is not available in this view.'}[e.code]||('Analysis failed: '+(e.message||e.code))}}
const APPD={'C-1042':{Name:'Ravi Kumar','DOB':'12-03-1998','Cert. no.':'ST/MP/2019/44821'},'C-1051':{Name:'Rahul Sharma',Income:'5,20,000'}};
