const docs=a=>'<div style="margin:6px 0"><b>Document status</b>'+CFG.docs.map(d=>{const n=d=='Income Certificate',w=n&&a.act,l=n?(a.act?'Needs correction':a.up?'Awaiting officer':'Verified'):'Verified';return `<div class="f">${w?'⚠':n&&a.up?'⏳':'✓'} ${d} <span class="tag ${w?'w':'o'}">${l}</span></div>`}).join('')+'</div>';
const G=['Open','Assigned','Under review','Resolved'];
