function showAuth0(m){m=m||'in';const up=m=='up';$('app').hidden=true;$('auth').hidden=false;$('auth').innerHTML=`<div class="aw"><section class="ah"><div class="brand">${LOGO}<b class="wm" style="font-size:20px">ANUGAM <span>360</span></b></div><h1>Welcome</h1><p>One place to apply, verify and track ST scholarship and fellowship cases: clear stages, explained AI flags, and human decisions.</p><ul><li>${ico(P.check)} Every application is a digital case file</li><li>${ico(P.check)} Explainable AI flags, officers decide</li><li>${ico(P.check)} Complete audit trail for every action</li></ul>${ART.cap}</section><section class="af"><div class="tabs2"><button class="${up?'':'on'}" onclick="showAuth('in')">Log in</button><button class="${up?'on':''}" onclick="showAuth('up')">Sign up</button></div><h2>${up?'Create your account':'Welcome back'}</h2>${up?'<label for="aN">Full name</label><input id="aN" autocomplete="name">':''}<label for="aE">Email</label><input id="aE" type="email" autocomplete="email"><label for="aP">Password</label><input id="aP" type="password" autocomplete="${up?'new-password':'current-password'}"><label for="aR">I am a</label><select id="aR"><option value="Applicant">Applicant (student)</option><option value="Officer">Verification Officer</option><option value="Committee">Selection Committee member</option><option value="Ministry">Ministry Admin</option></select><label class="chk"><input type="checkbox" id="aD" checked> Demo mode: let me switch between all roles</label><div class="msg" id="ae" role="alert"></div><button class="p wide" onclick="doAuth('${m}')">${up?'Create account':'Log in'}</button><button class="s wide" onclick="doAuth('guest')">Continue as guest (demo)</button><p class="note">Prototype only: no account is created or verified, and your password is never stored or sent anywhere.</p><button class="lnk" onclick="L=L=='en'?'hi':'en';showAuth('${m}')">${L=='en'?'हिन्दी':'English'}</button></section></div>`}
/* SALT keeps its original value on purpose: changing it would invalidate every existing demo student's password hash. */
const UK='mota-users',SALT='adhikar-demo-v2:',OFFPW='Demo@1234';
const OFF=[{email:'officer@mota.demo',name:'Verification Officer',role:'Officer'},{email:'committee@mota.demo',name:'Committee Member',role:'Committee'},{email:'admin@mota.demo',name:'Ministry Admin',role:'Ministry'}];
const H=async x=>{try{const b=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(x));return[...new Uint8Array(b)].map(v=>v.toString(16).padStart(2,'0')).join('')}catch(e){return'x'+btoa(unescape(encodeURIComponent(x)))}};
const users=()=>{try{return JSON.parse(localStorage.getItem(UK))||[]}catch(e){return[]}};
function fillAcc(e){$('aE').value=e;$('aP').value=OFFPW}
async function doAuth(m){const err=$('ae');err.textContent='';let u;
if(m=='guest')u={name:'Guest',role:'Applicant',email:''};
else{const up=m=='up',e=$('aE').value.trim().toLowerCase(),pw=$('aP').value,nm=up?$('aN').value.trim():'';
if(up&&!nm){err.textContent='Please enter your full name.';return}
if(!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(e)){err.textContent='Enter a valid email address.';return}
if(up){if(pw.length<8||!/\d/.test(pw)||!/[A-Za-z]/.test(pw)){err.textContent='Use at least 8 characters with letters and a number.';return}
if(OFF.some(o=>o.email==e)||users().some(x=>x.email==e)){err.textContent='An account with this email already exists. Please log in.';return}
const us=users();us.push({email:e,name:nm,role:'Applicant',h:await H(SALT+pw)});try{localStorage.setItem(UK,JSON.stringify(us))}catch(x){}u={name:nm,role:'Applicant',email:e}}
else{if(!pw){err.textContent='Enter your password.';return}const h=await H(SALT+pw),o=OFF.find(x=>x.email==e);
if(o){if(h!=await H(SALT+OFFPW)){err.textContent='Incorrect email or password.';return}u=o}
else{const st=users().find(x=>x.email==e);if(!st){err.textContent='No account found. Students can create an account; officials use the credentials issued by their department.';return}if(st.h!=h){err.textContent='Incorrect email or password.';return}u=st}}
$('aP').value=''}
ses={v:2,name:u.name,role:u.role,email:u.email||'',demo:false};if(ses.email){try{localStorage.setItem('mota-session',JSON.stringify(ses))}catch(x){}}
$('auth').hidden=true;$('app').hidden=false;tab=ROLETABS[ses.role][0];if(m=='up'){showOnboard();return}$('auth').hidden=true;$('app').hidden=false;go();toast('Welcome, '+fn()+'!')}
function signOut(){ses=null;try{localStorage.removeItem('mota-session')}catch(x){}showChoice()}
function boot(){try{ses=JSON.parse(localStorage.getItem('mota-session'))}catch(e){ses=null}if(ses&&ses.v==2&&ses.email&&ROLETABS[ses.role]){$('auth').hidden=true;$('app').hidden=false;if(!tabs().includes(tab))tab=tabs()[0];go()}else{if(ses&&!ses.email){try{localStorage.removeItem('mota-session')}catch(x){}}ses=null;showLanding()}}
function donut(){const D=[['Verified',7240,'var(--ok)'],['Under verification',2310,'var(--pri)'],['Deficient',864,'var(--bad)'],['Other',2066,'var(--mut)']],T=12480,R=42,C=2*Math.PI*R;let o=0;const seg=D.map(d=>{const l=d[1]/T*C,x=`<circle cx="60" cy="60" r="${R}" fill="none" stroke="${d[2]}" stroke-width="16" stroke-dasharray="${l} ${C-l}" stroke-dashoffset="${-o}" transform="rotate(-90 60 60)"/>`;o+=l;return x}).join('');return `<div style="display:flex;gap:16px;align-items:center;flex-wrap:wrap"><svg viewBox="0 0 120 120" width="150" height="150" role="img" aria-label="Applications by status (demo)">${seg}<text x="60" y="58" text-anchor="middle" font-size="16" font-weight="700" fill="var(--ink)">12,480</text><text x="60" y="73" text-anchor="middle" font-size="8" fill="var(--mut)">applications</text></svg><div>${D.map(d=>`<div class="leg"><i style="background:${d[2]}"></i>${d[0]} <b>${d[1].toLocaleString('en-IN')}</b></div>`).join('')}</div></div>`}
function tl(s){return '<div class="tl">'+ST.map((x,i)=>`<div class="${i<s?'done':i==s?'cur':''}">${i<s?'✓ ':''}${x}</div>`).join('')+'</div>'}
function applicant(){return `<div class="hero"><div><h2>${t('hi')}, ${fn()}</h2><p>Your applications, documents and next steps in one place.</p><div class="pir qa"><button class="s" onclick="showExplore()">Explore scholarships</button><button class="s" onclick="showDocCheck()">Check my documents</button></div></div>${ART.cap}</div>`+trackUI()+`
<div class="c" style="margin-top:12px"><h3>Notifications (${N.length})</h3>${N.length?N.slice(0,4).map(n=>`<div class="f"><small>${n.t}</small> ${n.s}</div>`).join(''):'Nothing new.'}</div><div class="g g2" style="margin-top:12px"><div class="c">${eligBox()}</div>
<div class="c"><h3>Grievance</h3><p>Status: <b>${grv<0?'None raised':G[grv]}</b></p><p>Flow: ${G.join(' → ')} (assumed; brief was cut off here)</p><button class="s" onclick="grievance()">${grv<0?'Raise a grievance':'Advance (demo: officer action)'}</button><hr style="border:0;border-top:1px solid var(--line)"><h3>Ask about schemes</h3><input id="q" placeholder="e.g. Which documents do I need?"><p><button class="s" onclick="ask()">Ask</button></p><div id="ar"></div></div></div>`}
function why(i){const a=apps[i];$('w'+i).innerHTML=`<div class="c"><b>Current stage:</b> ${ST[a.s]}<br><b>Reason:</b> ${a.act?'Waiting for your corrected Income Certificate.':a.s<5?'Waiting for the Selection Committee sitting.':a.s==5?'Selected. Waiting for the sanction order.':a.s==6?'Sanction issued. Waiting for disbursement.':'Disbursement done. No action pending.'}<br><b>You need to act:</b> ${a.act?'Yes':'No'}<br><b>Next step:</b> ${ST[a.s+1]||'None (completed)'}${a.s<7?' (configured SLA 3 days)':''}</div>`}
function upl(i){apps[i].act='';apps[i].up=1;cases[1].st='Open';note('Corrected Income Certificate received. AI pre-check passed. Waiting for official verification.');log('Applicant','Uploaded corrected Income Certificate','Deficient','Re-submitted','Applicant response');go()}
function elig(){const r=CFG.rules,i=+$('ei').value,ch=[['Category '+r.cat,$('ec').value==r.cat],['Qualification',r.quals.includes($('eq').value)],['Income up to Rs '+r.maxIncome.toLocaleString('en-IN')+' (demo)',i<=r.maxIncome]];const ok=ch.every(c=>c[1]);$('er').innerHTML=ch.map(c=>(c[1]?'✓ ':'✗ ')+c[0]).join('<br>')+`<p><b>${ok?'Appears eligible based on the information provided for '+CFG.scheme+'.':'Does not appear to meet the configured criteria.'}</b><br><small>Not a guarantee of selection. Rules are checked by a deterministic engine.</small></p>`}
function ask(){const q=$('q').value.toLowerCase();const kb={document:'Configured documents: '+CFG.docs.join(', ')+'.',income:'The income limit is set in the active scheme version (demo value).',status:'Open "Why is my application delayed?" on your application card.'};const k=Object.keys(kb).find(x=>q.includes(x));$('ar').innerHTML=k?kb[k]:'I can only answer from approved scheme material, and I have nothing on that. Please raise a grievance or contact the helpdesk.'}
function grievance(){grv=grv<0?0:Math.min(3,grv+1);log(grv?'Officer':'Applicant','Grievance '+G[grv],'-',G[grv],'');note('Grievance status: '+G[grv]);go()}
function officer(){const c=cases[sel];return `<h2>Verification workspace</h2><div class="g k"><div class="c kpi"><b>${cases.filter(x=>x.st=='Open').length}</b><span>Pending</span></div><div class="c kpi"><b>1</b><span>High priority</span></div><div class="c kpi"><b>1</b><span>SLA breach</span></div><div class="c kpi"><b>2</b><span>AI flagged</span></div></div>
<div class="g" style="grid-template-columns:200px 1fr;margin-top:12px"><div class="list">${cases.map((x,i)=>`<button class="cs ${i==sel?'on':''}" onclick="sel=${i};go()"><b>${x.id}</b> ${x.nm}<br><small>${x.sc} · ${x.pr} · ${x.st}</small></button>`).join('')}</div>
<div><div class="c" style="margin-bottom:12px">${live(c)}</div><div class="g g3"><div class="c"><h3>Document</h3><div class="doc"><b>GOVERNMENT CERTIFICATE (mock)</b><hr>Name: <mark>${c.x[0][1]}</mark><br>${c.x.slice(1).map(r=>r[0]+': '+r[1]).join('<br>')}<div class="st">seal?</div></div></div>
<div class="c"><h3>Extracted fields</h3>${c.x.map(r=>`<div class="f"><small>${r[0]}</small><br><b>${r[1]}</b> <span class="tag ${r[2]<80?'w':'o'}">${r[2]}%</span></div>`).join('')}</div>
<div class="c"><h3>Application vs document</h3>${cmp(c)}<h3>AI and rule findings</h3>${c.f.map(f=>`<div class="f">${f[0]=='ok'?'✓':'⚠'} ${f[1]}</div>`).join('')}<p><small>Recommended: ${c.rec}. Signals are not fraud verdicts.</small></p><label>Applicant message (AI draft, edit before sending)</label><textarea id="dm" rows="3">${c.msg}</textarea><label>Officer reason (required)</label><textarea id="rs" rows="2"></textarea><div class="msg" id="m"></div>
${['Accept','Request Correction','Flag for Review','Escalate'].map(a=>`<button class="${a=='Accept'?'p':'s'}" onclick="act('${a}')">${a}</button>`).join(' ')}</div></div></div></div>`}
function act(a){const r=$('rs').value.trim();if(!r){$('m').textContent='Enter a reason. Every action is recorded.';return}const c=cases[sel],ap=apps[1];log('Officer',a+' '+c.id,c.st,a,r);c.st=a;
if(c.link!==undefined){if(a=='Request Correction'){const m=$('dm').value.trim()||c.msg;ap.act=m;ap.up=0;note('Action required on '+ap.n+': '+m)}if(a=='Accept'){ap.act='';ap.up=0;ap.s=4;note(ap.n+': documents verified. Moved to Committee Review.')}}
go()}
function score(c){return (c.ac*CFG.merit.Academic+c.pr*CFG.merit.Proposal+(+c.iv||0)*CFG.merit.Interview)/100}
function committee(){return committee0()+sanPanel()}function committee0(){const m=CFG.merit;return `<h2>Selection committee</h2><div class="demo">Ranking is a plain weighted sum of the configured merit components (${Object.entries(m).map(e=>e[0]+' '+e[1]+'%').join(', ')}). No AI ranks candidates. Members enter scores; the decision stays with the authorised committee.</div><div class="c"><table><tr><th>Candidate</th><th>Eligibility</th><th>Documents</th><th>Academic</th><th>Proposal</th><th>Interview</th><th>Total</th><th>Decision and comment</th></tr>${cand.map((c,i)=>c.ap==1&&apps[1].s<4?'':`<tr><td>${c.nm}</td><td><span class="tag o">Pre-check passed</span></td><td><span class="tag o">Verified</span></td><td>${c.ac}</td><td>${c.pr}</td><td><input type="number" style="width:70px" value="${c.iv}" onchange="cand[${i}].iv=this.value;go()"></td><td><b>${score(c).toFixed(1)}</b></td><td>${c.fin?`<b>${c.dec}</b><br><b>Final: ${c.fin}</b>`:c.dec&&c.dec.startsWith('Recommended')?`<b>${c.dec}</b><br><input id="fm${i}" placeholder="Chair's final decision reason (required)"><button class="p" onclick="fin(${i},'Selected')">Select</button> <button class="s" onclick="fin(${i},'Not selected')">Not selected</button>`:c.dec?`<b>${c.dec}</b>`:`<input id="cm${i}" placeholder="Comment (required)"><button class="p" onclick="dec(${i},'Recommended')">Recommend</button> <button class="s" onclick="dec(${i},'On hold')">Hold</button>`}</td></tr>`).join('')}</table></div>`}
