const HK=Object.keys(HI).sort((a,b)=>b.length-a.length),ORIG=new WeakMap();
function trDom(){const w=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT,{acceptNode:n=>/^(SCRIPT|STYLE|TEXTAREA|PRE)$/.test(n.parentNode.nodeName)?NodeFilter.FILTER_REJECT:NodeFilter.FILTER_ACCEPT});let n;while(n=w.nextNode()){if(!ORIG.has(n))ORIG.set(n,n.nodeValue);let t=ORIG.get(n);if(L=='hi')HK.forEach(k=>{t=t.split(k).join(HI[k])});if(n.nodeValue!==t)n.nodeValue=t}}
function addLinked(){if(!cand.some(c=>c.ap!==undefined))cand.push({nm:'Rahul Sharma (NFST)',ac:78,pr:72,iv:'',dec:'',ap:0},{nm:'Rahul Sharma (NOS)',ac:81,pr:69,iv:'',dec:'',ap:1})}
function fin(i,d){const r=$('fm'+i).value.trim();if(!r){$('fm'+i).style.borderColor='var(--bad)';return}const c=cand[i],ap=c.ap!==undefined?apps[c.ap]:null;c.fin=d;log('Committee chair','Final decision: '+d+' '+c.nm,'Recommended',d,r);if(ap){if(d=='Selected'){ap.s=5;note(ap.n+': you have been selected. Sanction order is being prepared.')}else{ap.out='Not selected in this round';note(ap.n+': not selected in this round.')}}go()}
function sanc(i,k){const r=$('sr'+i).value.trim();if(!r){$('sr'+i).style.borderColor='var(--bad)';return}const c=cand[i],ap=c.ap!==undefined?apps[c.ap]:null;c.san=k;log('Ministry admin',(k==1?'Sanction issued ':'Disbursement recorded ')+c.nm,k==1?'Selected':'Sanctioned',k==1?'Sanctioned':'Disbursed',r+' (mock PFMS adapter)');if(ap){ap.s=k==1?6:7;payRec(ap,k,r);note(ap.n+(k==1?': sanction order issued.':': first instalment disbursed (simulated).'))}go()}
function sanPanel(){const l=cand.map((c,i)=>[c,i]).filter(x=>x[0].fin=='Selected');if(!l.length)return'';return `<div class="c" style="margin-top:12px"><h3>Sanction and disbursement (Ministry)</h3><table><tr><th>Candidate</th><th>Status</th><th></th></tr>${l.map(([c,i])=>`<tr><td>${c.nm}</td><td>${['Sanction pending','Sanctioned','Disbursed'][c.san||0]}</td><td>${(c.san||0)<2?`<input id="sr${i}" placeholder="Order / reference no. (required)"><button class="p" onclick="sanc(${i},${(c.san||0)+1})">${c.san?'Record disbursement':'Issue sanction'}</button>`:'Complete'}</td></tr>`).join('')}</table><small>Disbursement uses a mock PFMS adapter: no real payment is made.</small></div>`}
function dec(i,d){const c=$('cm'+i).value.trim();if(!c){$('cm'+i).style.borderColor='var(--bad)';return}cand[i].dec=d+': '+c;log('Committee',d+' '+cand[i].nm,'Evaluated',d,c);go()}
function bars(a,hot){const mx=Math.max(...a.map(x=>x[1]));return a.map(x=>`<div class="row"><span class="l">${x[0]}</span><div class="bar ${x[1]==mx&&hot?'hot':''}" style="width:${x[1]/mx*60}%"></div><b>${x[1]}${hot?' d':''}</b>${x[1]==mx&&hot?' <span class="tag b">BOTTLENECK</span>':''}</div>`).join('')}
function command(){return `<h2>Ministry command centre</h2><div class="demo">Simulated data.</div><div class="g k">${[['Total','12,480'],['Submitted','11,902'],['Under verification','2,310'],['Deficient','864'],['Verified','7,240'],['Eligible','6,980'],['Selected','1,150'],['Avg processing','11.8 d']].map(k=>`<div class="c kpi"><i>${ico(P[KI[k[0]]]||P.files)}</i><b>${k[1]}</b><span>${k[0]}</span></div>`).join('')}</div>
<div class="g g2" style="margin-top:12px"><div class="c"><h3>Applications by status</h3>${donut()}</div><div class="c"><h3>Days spent per stage</h3>${bars([['Application',0.8],['Verification',3.7],['Scrutiny',2.1],['Selection',5.2]].map(x=>x),1)}<small>Verification runs past its ${'3-day'} configured SLA; selection is longest but committee-paced.</small></div>
<div class="c"><h3>Top deficiencies</h3>${bars([['Income cert unclear',312],['Name mismatch',241],['Expired document',167],['Missing page',96],['Seal missing',48]])}</div>
<div class="c"><h3>Verification backlog by state</h3>${bars([['Madhya Pradesh',540],['Odisha',480],['Jharkhand',390],['Chhattisgarh',350],['Gujarat',210]])}</div>
<div class="c"><h3>Review signals (not verdicts)</h3>${bars([['Repeated bank account',22],['Same certificate no.',14],['Identical files',9],['Record inconsistencies',31]])}</div><div class="c"><h3>Aging and SLA</h3><table><tr><th>Age</th><th>Cases</th></tr><tr><td>0-3 days</td><td>1,420</td></tr><tr><td>4-7 days</td><td>610</td></tr><tr><td>8+ days <span class="tag b">SLA breach</span></td><td>280</td></tr></table></div></div>`}
function engine(){return `<h2>Scheme engine</h2><div class="g g2"><div class="c"><h3>${CFG.scheme} active version v${CFG.ver} (demo)</h3><label>Max family income (Rs), demo value</label><input id="mi" type="number" value="${CFG.rules.maxIncome}"><label>Accepted qualifications (comma separated)</label><input id="mq" value="${CFG.rules.quals.join(',')}"><label>Required documents</label><input id="md" value="${CFG.docs.join(',')}"><label>Reason for change</label><input id="mr"><div class="msg" id="m"></div><button class="p" onclick="pub()">Publish as new version</button><p><small>No code change needed: eligibility and document rules are read from this configuration. Older versions stay on record for cases already filed.</small></p></div>
<div class="c"><h3>Configuration (JSON)</h3><pre style="overflow:auto;font-size:12px">${JSON.stringify({scheme:CFG.scheme,version:CFG.ver,eligibility:CFG.rules,selection:{method:'weighted merit + committee',weights:CFG.merit},documents:CFG.docs,workflow:{stages:ST,sla_days:{Verification:3,Scrutiny:2}}},null,1)}</pre></div><div class="c"><h3>Integration adapters</h3><table><tr><th>System</th><th>Purpose</th><th>Status</th></tr><tr><td>DigiLocker</td><td>Fetch issued documents</td><td><span class="tag w">Mock</span></td></tr><tr><td>NSP dedup check</td><td>Cross-portal duplicates</td><td><span class="tag w">Mock</span></td></tr><tr><td>PFMS</td><td>Payment status</td><td><span class="tag w">Mock</span></td></tr><tr><td>SMS / email</td><td>Notifications</td><td><span class="tag w">Mock</span></td></tr></table><small>No live government API is claimed. Each adapter is swapped for a real one only when an official API is approved.</small></div></div>`}
function pub(){const r=$('mr').value.trim();if(!r){$('m').textContent='A reason is required for a new version.';return}const o=CFG.ver;CFG.rules.maxIncome=+$('mi').value;CFG.rules.quals=$('mq').value.split(',').map(s=>s.trim());CFG.docs=$('md').value.split(',').map(s=>s.trim());CFG.ver++;log('Ministry admin','Published '+CFG.scheme+' v'+CFG.ver,'v'+o,'v'+CFG.ver,r);go()}
function audit(){return `<h2>Audit trail</h2><div class="c"><table><tr><th>Time</th><th>Who</th><th>Action</th><th>Before</th><th>After</th><th>Reason</th></tr>${aud.map(a=>`<tr><td>${a.t}</td><td>${a.r}</td><td>${a.a}</td><td>${a.p}</td><td>${a.n}</td><td>${a.why}</td></tr>`).join('')}</table></div>`}
function go(){if(ses&&!tabs().includes(tab))tab=tabs()[0];save();nav();$('v').innerHTML={Applicant:applicant,Officer:officer,Committee:committee,'Command Centre':command,'Scheme Engine':engine,Audit:audit}[tab]()}
/* ---- Stage 1: public entry (intro -> choice -> explore). Rendered into #auth; no account needed to browse. ---- */
const eligBox=()=>`<h3>Check eligibility</h3><label>Category</label><select id="ec"><option>ST</option><option>Other</option></select><label>Highest education</label><select id="eq"><option>Master's</option><option>MPhil</option><option>Graduate</option></select><label>Annual family income (Rs)</label><input id="ei" type="number" value="600000"><p><button class="p" onclick="elig()">${t('chk')}</button></p><div id="er"></div>`;
P.search='<circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/>';
const ptop=r=>`<div class="pt"><div class="brand">${LOGO}<b class="wm">ANUGAM <span>360</span></b></div><div class="pta">${r||''}</div></div>`;
function pubShell(h){$('app').hidden=true;$('auth').hidden=false;$('auth').innerHTML=`<div class="pw">${h}</div>`}
function showAuth(m){showAuth0(m);const f=document.querySelector('.af');if(!f)return;['label[for=aR]','#aR','label.chk'].forEach(q=>{const e=f.querySelector(q);e&&e.remove()});f.insertAdjacentHTML('afterbegin','<button class="lnk" onclick="showChoice()">\u2190 Back</button>');
const hint=m=='up'?'<small>Student accounts only. Officials receive their accounts from the department.</small>':'<details class="demoacc"><summary>Official login (demo accounts)</summary><small>Official accounts are provisioned, not self-registered. Demo password: <b>'+OFFPW+'</b></small><br>'+OFF.map(o=>`<button class="lnk" onclick="fillAcc('${o.email}')">${o.name}</button>`).join(' ')+'</details>';
f.querySelector('#ae').insertAdjacentHTML('beforebegin',hint);const n=f.querySelector('.note');if(n)n.textContent='Prototype only: accounts and a salted password hash stay in this browser; nothing is sent anywhere. This is not real security.'}
function showChoice(){showLanding()}
/* Journey entry points. live=1 works now; the rest are placeholders for later stages. */
const INT=[['find','Find Scholarships For Me','Matches based on your details','search',1],['explore','Explore Scholarships','Schemes, benefits and documents','files',1],['docs','Check My Documents','Spot problems before you submit','check',1],['apply','Apply','Guided application','send',1],['track','Track My Application','Stage, status and next steps','clock',1]];
function enterApp(){$('auth').hidden=true;$('app').hidden=false;if(!tabs().includes(tab))tab=tabs()[0];go()}
function intent(k){if(k=='explore')return showExplore();if(k=='find')return showFind();if(k=='track'){if(ses)return enterApp();showAuth('in');return toast('Log in to track your application')}if(k=='docs')return showDocCheck();if(k=='apply'){showExplore();const l=$('dl');l&&l.scrollIntoView({behavior:'smooth',block:'start'});return toast('Pick a scholarship, then press Apply.')}toast('Coming in an upcoming update')}
function showExplore(){dfrom='explore';const a=ses?'<button class="s" onclick="enterApp()">My dashboard</button>':'<button class="s" onclick="showAuth(\'in\')">Log in</button> <button class="p" onclick="showAuth(\'up\')">Sign up</button>';pubShell(ptop('<button class="s" onclick="showChoice()">Home</button> '+a)+`<section class="pv pvx"><h1>Scholarships for ST students</h1><p>Browse freely. Checking eligibility or using AI is optional.</p><button class="lnk" onclick="showOnboard()">Answer a few quick questions (optional)</button><div class="pit">${INT.map(x=>`<button class="itile" onclick="intent('${x[0]}')"><i>${ico(P[x[3]])}</i><b>${x[1]}</b><small>${x[2]}</small>${x[4]?'':'<span class="tag w">Coming soon</span>'}</button>`).join('')}</div>${browseUI()}<div class="c" style="margin-top:12px"><small>Optional: not required to browse.</small>${eligBox()}</div><div class="demo" style="margin-top:12px">Simulated prototype. Scheme rules and limits are demo values, not official. Check the official portal before applying.</div></section>`);prefill()}
/* ---- Stage 3: student onboarding. One question at a time, adaptive, every question skippable. Answers only personalise; no eligibility verdict here. ---- */
const PF='mota-profiles',pkey=()=>ses&&ses.email||'guest';
const getProf=()=>{try{return(JSON.parse(localStorage.getItem(PF))||{})[pkey()]||null}catch(e){return null}};
const setProf=p=>{try{const a=JSON.parse(localStorage.getItem(PF))||{};a[pkey()]=p;localStorage.setItem(PF,JSON.stringify(a))}catch(e){}};
let ob={a:{},h:[]};
const ONE=a=>a.purpose=='find'||a.purpose=='apply',PROF=a=>ONE(a)&&a.cat!='Other';
const OQ=[
{k:'purpose',q:'What would you like help with?',o:[['find','Finding scholarships'],['explore','Exploring scholarship options'],['understand','Understanding a scholarship'],['docs','Checking my documents']]},
{k:'doc',q:'Which document would you like to check?',o:()=>CFG.docs.map(d=>[d,d]).concat([['na','Not sure yet']]),show:a=>a.purpose=='docs'},
{k:'cat',q:'Which category do you belong to?',o:[['ST','Scheduled Tribe (ST)'],['Other','Another category'],['na','Prefer not to say']],show:ONE},
{k:'edu',q:'What is your highest education so far?',o:[['Class 12','Class 12 or below'],['Graduate','Graduate'],["Master's","Master's"],['MPhil','MPhil or PhD'],['na','Prefer not to say']],show:PROF},
{k:'plan',q:"Are you planning to study a Master's or research programme?",o:[['yes','Yes'],['later','Not yet'],['na','Not sure']],show:a=>PROF(a)&&a.edu=='Graduate'},
{k:'inc',q:"Roughly, what is your family's yearly income?",o:[['lt250','Below Rs 2.5 lakh'],['250-800','Rs 2.5 to 8 lakh'],['gt800','Above Rs 8 lakh'],['na','Prefer not to say']],show:PROF}];
const optsOf=q=>typeof q.o=='function'?q.o():q.o;
const obCur=()=>OQ.find(q=>(!q.show||q.show(ob.a))&&!(q.k in ob.a));
const PL={understand:'Understand a scholarship',explore:'Explore scholarships',find:'Find scholarships for me',docs:'Check my documents',apply:'Apply',track:'Track my application'};
function showOnboard(){ob={a:{},h:[]};obShow()}
function obShow(){const q=obCur();if(!q)return obSummary();const n=ob.h.length+1;
pubShell(ptop('<button class="s" onclick="obSkipAll()">Skip for now</button>')+`<section class="pv pvi"><small>Question ${n} (optional)</small><h1>${q.q}</h1><div class="opts">${optsOf(q).map((x,i)=>`<button class="opt" onclick="obPick(${i})">${x[1]}</button>`).join('')}</div><div class="pir">${ob.h.length?'<button class="s" onclick="obBack()">Back</button>':''}<button class="lnk" onclick="obPick(-1)">${n==1?'Skip questions':'Skip this question'}</button></div><p class="note">Your answers help personalise what you see. You can skip any question.</p></section>`)}
function obPick(i){const q=obCur();if(!q)return;ob.a[q.k]=i<0?'':optsOf(q)[i][0];ob.h.push(q.k);obShow()}
function obBack(){const k=ob.h.pop();if(k)delete ob.a[k];obShow()}
function obSkipAll(){setProf({a:ob.a,skipped:1,t:Date.now()});ses?enterApp():showExplore()}
function obGo(p){if(p=='track')return intent('track');if(p=='find')return showFind();if(p=='docs')return showDocCheck();if(p=='apply')return intent('apply');showExplore()}
function obSummary(){setProf({a:ob.a,t:Date.now()});const a=ob.a,p=a.purpose||'explore';
const rows=Object.keys(a).filter(k=>a[k]&&a[k]!='na').map(k=>{const q=OQ.find(x=>x.k==k),o=optsOf(q).find(x=>x[0]==a[k]);return`<div class="f"><small>${q.q}</small><br><b>${o?o[1]:a[k]}</b></div>`}).join('');
const nt=a.cat=='Other'?'<p>These schemes are for Scheduled Tribe students, but you are welcome to browse them.</p>':'',soon='';
pubShell(ptop()+`<section class="pv pvi"><h1>Thanks, you are all set</h1>${rows?'<div style="text-align:left">'+rows+'</div>':'<p>No answers saved. You can still explore everything.</p>'}${nt}${soon}<div class="pcb"><button class="p wide" onclick="obGo('${p}')">${PL[p]}</button>${p!='explore'?'<button class="s wide" onclick="showExplore()">Explore scholarships</button>':''}${ses?'<button class="s wide" onclick="enterApp()">My dashboard</button>':''}</div><button class="lnk" onclick="showOnboard()">Change my answers</button></section>`)}
function prefill(){const a=(getProf()||{}).a||{},c=$('ec'),e=$('eq');if(c&&(a.cat=='ST'||a.cat=='Other'))c.value=a.cat;if(e&&['Graduate',"Master's",'MPhil'].includes(a.edu))e.value=a.edu}
/* ---- Stage 4: scholarship discovery. Browse, search, filter, match, detail. Matching is rule-based; the optional text helper only fills the form and the user confirms. ---- */
let dfrom='explore';
const catalog=()=>{const O=['PRE','POST','TOP','NFST','NOS'];return SCH.map(s=>s.id=='NFST'?Object.assign({},s,{edu:CFG.rules.quals,maxIncome:CFG.rules.maxIncome,docs:CFG.docs,ver:'v'+CFG.ver}):s).sort((a,b)=>O.indexOf(a.id)-O.indexOf(b.id))};
const inr=n=>'Rs '+n.toLocaleString('en-IN');
function sstat(s){const d=Math.ceil((new Date(s.deadline+'T23:59:59')-new Date())/864e5);return d<0?{t:'Closed',c:'b',d}:d<=30?{t:'Closing soon',c:'w',d}:{t:'Open',c:'o',d}}
const BAND={lt250:[0,250000],'250-800':[250000,800000],gt800:[800000,1e12]},EDUO=[['Class 12','Class 12 or below'],['Graduate','Graduate'],["Master's","Master's"],['MPhil','MPhil or PhD']],INCO=[['lt250','Below Rs 2.5 lakh'],['250-800','Rs 2.5 to 8 lakh'],['gt800','Above Rs 8 lakh']];
function match(s,f){const b=BAND[f.inc],pg=f.edu=='Graduate'&&f.plan=='yes'&&s.edu.includes("Master's");
const c=[['Category '+s.cat,f.cat?(f.cat==s.cat?'ok':'no'):'unk'],['Education: '+s.level,f.edu?(s.edu.includes(f.edu)||pg?'ok':'no'):'unk'],['Income up to '+inr(s.maxIncome)+' (demo)',b?(b[1]<=s.maxIncome?'ok':b[0]>=s.maxIncome?'no':'maybe'):'unk']];
const fit=c.some(x=>x[1]=='no')?3:c.some(x=>x[1]=='maybe')?1:c.some(x=>x[1]=='unk')?2:0;return{c,fit,t:['Likely fits','May fit','Need more details','Unlikely'][fit]}}
const FT=['o','w','w','b'],chips=c=>c.map(x=>`<span class="tag ${x[1]=='ok'?'o':x[1]=='no'?'b':'w'}">${{ok:'\u2713',no:'\u2717',maybe:'~',unk:'?'}[x[1]]} ${x[0]}</span>`).join(' ');
const dCards=(l,fm)=>l.length?l.map(s=>{const st=sstat(s),m=fm?match(s,fm):null;return`<div class="c sc"><div class="scr"><b>${s.name}</b><span class="tag ${st.c}">${st.t}</span></div><small>${s.level}</small><p>${s.short}</p>${m?`<p><span class="tag ${FT[m.fit]}">${m.t}</span></p><div class="chips">${chips(m.c)}</div>`:''}<p><button class="s" onclick="showScheme('${s.id}')">View details</button></p></div>`}).join(''):'<div class="c empty"><p><b>No scholarships match.</b></p><p>Try a different word or clear the filters.</p><button class="s" onclick="dClear()">Clear search and filters</button></div>';
function dClear(){const q=$('sq'),l=$('sl'),o=$('so');if(!q)return;q.value='';l.value='';o.checked=false;dList();q.focus()}
function dList(){const q=($('sq').value||'').trim().toLowerCase(),l=$('sl').value,o=$('so').checked;$('dl').innerHTML=dCards(catalog().filter(s=>(!q||(s.name+' '+s.short+' '+s.level+' '+s.benefits.join(' ')).toLowerCase().includes(q))&&(!l||s.level==l)&&(!o||sstat(s).t!='Closed')))}
const browseUI=()=>`<h2>Scholarships</h2><div class="dfil"><input id="sq" type="search" placeholder="Search scholarships" oninput="dList()" aria-label="Search scholarships"><select id="sl" onchange="dList()" aria-label="Filter by level"><option value="">All levels</option>${[...new Set(SCH.map(s=>s.level))].map(x=>`<option>${x}</option>`).join('')}</select><label class="dchk"><input type="checkbox" id="so" onchange="dList()"> Open now</label></div><div id="dl">${dCards(catalog())}</div>`;
const DEMO='<div class="demo" style="margin-top:12px">Simulated prototype. Scholarship rules, limits and dates are demo values, not official. Check the official portal before applying. Matches are a guide, not an eligibility decision.</div>';
function showScheme(id){const s=catalog().find(x=>x.id==id);if(!s)return;const st=sstat(s),p=(getProf()||{}).a||{},m=(p.cat||p.edu||p.inc)?match(s,p):null;
pubShell(ptop(`<button class="s" onclick="${dfrom=='find'?'showFind()':'showExplore()'}">\u2190 ${dfrom=='find'?'Back to matches':'Back to scholarships'}</button>`)+`<section class="pv pvx"><h1>${s.name}</h1><p><span class="tag ${st.c}">${st.t}</span> <span class="tag w">${s.level}</span></p><p>${s.short}</p>
${m?`<div class="c"><h3>How this may fit you</h3><span class="tag ${FT[m.fit]}">${m.t}</span><div class="chips">${chips(m.c)}</div><small>Based on your optional answers.</small></div>`:''}
<div class="c"><h3>Who can apply</h3><div class="f">Category: ${s.cat}</div><div class="f">Education: ${s.edu.join(', ')}</div><div class="f">Family income up to ${inr(s.maxIncome)} (demo value)</div></div>
<div class="c"><h3>Benefits</h3>${s.benefits.map(b=>`<div class="f">${b}</div>`).join('')}<small>Exact amounts are set by the scheme. Check the official portal.</small></div>
<div class="c"><h3>Documents you need</h3>${s.docs.map(d=>`<div class="f">\u2713 ${d}</div>`).join('')}</div>
<div class="c"><h3>Deadline</h3><div class="f">${new Date(s.deadline+'T12:00:00').toLocaleDateString('en-IN',{day:'numeric',month:'long',year:'numeric'})} (demo date)${st.d>=0?' \u00b7 '+st.d+' days left':''}</div></div>
<div class="c"><h3>Official information</h3><p>Rules, dates and the application itself are on the official portal.</p><a class="linkbtn alt" href="${s.portal}" target="_blank" rel="noopener noreferrer">Open official portal</a> <a class="linkbtn alt" href="https://dbttribal.gov.in/AllScheme.aspx" target="_blank" rel="noopener noreferrer">All MoTA schemes (DBT Tribal)</a></div>
${st.t=='Closed'?'<p class="dhs w"><b>The demo deadline for this scheme has passed.</b> You can still read the details. Check the official portal for current dates.</p>':''}${DEMO}<div class="stk"><button class="s" onclick="showDocCheck('${s.id}')">Check my documents</button><button class="p" onclick="startApply('${s.id}')">Apply</button></div></section>`)}
function showFind(){dfrom='find';const a=(getProf()||{}).a||{},sel=(id,l,o,v)=>`<label for="${id}">${l}</label><select id="${id}" onchange="fMatch()"><option value="">Not sure / skip</option>${o.map(x=>`<option value="${x[0]}" ${x[0]==v?'selected':''}>${x[1]}</option>`).join('')}</select>`;
pubShell(ptop('<button class="s" onclick="showChoice()">Home</button> <button class="s" onclick="showExplore()">Explore all</button>')+`<section class="pv pvx"><h1>Find scholarships for me</h1><p>Tell us a little. Everything is optional and you can change it any time.</p><div class="c">${sel('fc','Category',[['ST','Scheduled Tribe (ST)'],['Other','Another category']],a.cat)}${sel('fe','Education',EDUO,a.edu)}${sel('fi','Family income',INCO,a.inc)}<details class="demoacc"><summary>Optional: describe yourself in your own words</summary><textarea id="ft" rows="3" placeholder="e.g. I am an ST student finishing my BSc, family income about 4 lakh"></textarea><button class="s" onclick="aiRead()">Fill the form from my text</button><div class="msg" id="fnote"></div></details></div><div id="fr"></div>${DEMO}</section>`);fMatch()}
function fMatch(){const f={cat:$('fc').value,edu:$('fe').value,inc:$('fi').value,plan:((getProf()||{}).a||{}).plan},r=catalog().map(s=>[s,match(s,f)]).sort((x,y)=>x[1].fit-y[1].fit||x[0].id.localeCompare(y[0].id));$('fr').innerHTML='<h2>Matches</h2>'+dCards(r.map(x=>x[0]),f)}
function readText(t){t=t.toLowerCase();const r={cat:'',edu:'',inc:''};
if(/\b(st|scheduled tribes?|tribal|adivasi)\b/.test(t))r.cat='ST';else if(/\b(obc|sc|general|ews)\b/.test(t))r.cat='Other';
if(/phd|m\.?phil|research/.test(t))r.edu='MPhil';else if(/master|m\.?sc|\bm\.?a\b|postgrad|\bpg\b/.test(t))r.edu="Master's";else if(/graduat|b\.?sc|\bb\.?a\b|b\.?tech|bachelor|degree/.test(t))r.edu='Graduate';else if(/class (9|10|11|12)|school|10th|12th/.test(t))r.edu='Class 12';
let n=null,m=t.match(/(\d+(?:\.\d+)?)\s*(?:lakh|lac)/);if(m)n=+m[1]*1e5;else if(m=t.match(/(?:rs\.?|\u20b9)\s*([\d,]{5,})/))n=+m[1].replace(/,/g,'');
if(n!=null)r.inc=n<250000?'lt250':n<=800000?'250-800':'gt800';return r}
async function aiRead(){const t=$('ft').value.trim(),o=$('fnote');if(!t){o.textContent='Type a sentence or two first.';return}let r=null,eng='simple text reading in this browser';
try{if(window.claude&&claude.use){const S=await claude.use('sample'),j=await S.json('Extract JSON {"cat":"ST"|"Other"|"","edu":"Class 12"|"Graduate"|"Master\'s"|"MPhil"|"","inc":"lt250"|"250-800"|"gt800"|""} from this student description. Include only what is stated, otherwise "". Description: '+t);if(j&&typeof j=='object'){r=j;eng='AI'}}}catch(e){r=null}
if(!r)r=readText(t);[['fc','cat'],['fe','edu'],['fi','inc']].forEach(x=>{if(r[x[1]])$(x[0]).value=r[x[1]]});fMatch();o.textContent='Filled using '+eng+'. Please check the values above; you decide.'}
load();addLinked();new MutationObserver(trDom).observe(document.body,{childList:true,subtree:true});
